{"name": "addPet", "description": "Add a new pet to the store. — Add a new pet to the store.", "params": {"id": "integer", "name": "string*", "category": "object", "photoUrls": "array*", "tags": "array", "status": "string"}, "http_method": "POST", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": []}}
{"name": "findPetsByStatus", "description": "Finds Pets by status. — Multiple status values can be provided with comma separated strings.", "params": {"status": "string*"}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": []}}
{"name": "findPetsByTags", "description": "Finds Pets by tags. — Multiple tags can be provided with comma separated strings. Use tag1, tag2, tag3 for testing.", "params": {"tags": "array*"}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": []}}
{"name": "getPetById", "description": "Find pet by ID. — Returns a single pet.", "params": {"petId": "integer*"}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": []}}
{"name": "updatePetWithForm", "description": "Updates a pet in the store with form data. — Updates a pet resource based on the form data.", "params": {"petId": "integer*", "name": "string", "status": "string"}, "http_method": "POST", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": []}}
{"name": "deletePet", "description": "Deletes a pet. — Delete a pet.", "params": {"api_key": "string", "petId": "integer*"}, "http_method": "DELETE", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": ["api_key"]}}
{"name": "uploadFile", "description": "Uploads an image. — Upload image of the pet.", "params": {"petId": "integer*", "additionalMetadata": "string"}, "http_method": "POST", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": []}}
