{"name": "getOrderById", "description": "Find purchase order by ID. — For valid response try integer IDs with value <= 5 or > 10. Other values will generate exceptions.", "params": {"orderId": "integer*"}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": []}}
{"name": "deleteOrder", "description": "Delete purchase order by identifier. — For valid response try integer IDs with value < 1000. Anything above 1000 or non-integers will generate API errors.", "params": {"orderId": "integer*"}, "http_method": "DELETE", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": []}}
{"name": "createUser", "description": "Create user. — This can only be done by the logged in user.", "params": {"id": "integer", "username": "string", "firstName": "string", "lastName": "string", "email": "string", "password": "string", "phone": "string", "userStatus": "integer"}, "http_method": "POST", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": ["password"]}}
{"name": "createUsersWithListInput", "description": "Creates list of users with given input array. — Creates list of users with given input array.", "params": {"items": "object"}, "http_method": "POST", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": []}}
{"name": "loginUser", "description": "Logs user into the system. — Log into the system.", "params": {"username": "string", "password": "string"}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": ["password"]}}
{"name": "logoutUser", "description": "Logs out current logged in user session. — Log user out of the system.", "params": {}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": []}}
{"name": "getUserByName", "description": "Get user by user name. — Get user detail based on username.", "params": {"username": "string*"}, "http_method": "GET", "heuristic": {"risk": "read", "returns_untrusted": false, "sensitive": []}}
{"name": "updateUser", "description": "Update user resource. — This can only be done by the logged in user.", "params": {"username": "string", "id": "integer", "firstName": "string", "lastName": "string", "email": "string", "password": "string", "phone": "string", "userStatus": "integer"}, "http_method": "PUT", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": ["password"]}}
{"name": "deleteUser", "description": "Delete user resource. — This can only be done by the logged in user.", "params": {"username": "string*"}, "http_method": "DELETE", "heuristic": {"risk": "write", "returns_untrusted": false, "sensitive": []}}
DATA>>>
<<<DATA requirements
Customers may browse pets and place and view their own orders. Only staff may add, update or delete pets, and only staff may manage users. Nobody may do anything that is not needed for these tasks.
DATA>>>
<<<DATA roles
customer, staff
DATA>>>
